// ==UserScript==
// @name         Auto Hoài Niệm + Ns Mod (All-in-One)
// @namespace    vlmod
// @version      5.6
// @description  Auto Hoài Niệm + Ns Mod + Auto Dã Tẩu chạy ngầm + cập nhật GitHub tích hợp trong một userscript
// @match        *://hoainiem2003.net/*
// @match        *://*/*vltk*
// @match        https://volamidle.pages.dev/*
// @match        https://hoaniemi2003.net/vltk/*
// @run-at       document-start
// @grant        unsafeWindow
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_xmlhttpRequest
// @grant        GM.getValue
// @grant        GM.setValue
// @grant        GM.xmlHttpRequest
// @connect      raw.githubusercontent.com
// @connect      github.com
// @connect      githubusercontent.com
// @connect      api.github.com
// @connect      cdn.jsdelivr.net
// ==/UserScript==

/*
 * ALL-IN-ONE BOOTSTRAP
 * Chỉ cài userscript này. Không cần cài Auto_Updater_Bootstrap_Tampermonkey_Stay riêng.
 * Mã ứng dụng được nhúng dạng Base64 ở LOCAL_APP_B64 bên dưới để file này tự chạy được
 * ngay cả khi chưa có cache. Khi cập nhật, bản mới từ GitHub được lưu vào storage và
 * payload ứng dụng mới sẽ được nạp ở lần tải trang kế tiếp.
 */
(function () {
    'use strict';

    const INSTALLED_VERSION = '5.6';
    const RAW_URL = 'https://raw.githubusercontent.com/kaylypro123/hackidle/refs/heads/main/script.user.js';
    const JSDELIVR_URL = 'https://cdn.jsdelivr.net/gh/kaylypro123/hackidle@main/script.user.js';
    const API_URL = 'https://api.github.com/repos/kaylypro123/hackidle/contents/script.user.js?ref=main';
    const CODE_KEY = 'vlmod_all_in_one_source_v15';
    const VERSION_KEY = 'vlmod_all_in_one_version_v15';
    const PAGE = (typeof unsafeWindow !== 'undefined' && unsafeWindow) ? unsafeWindow : window;
    const failures = [];

    // Mã Auto Hoài Niệm + Ns Mod được nhúng ngay trong cùng userscript.
    const LOCAL_APP_B64 = '';

    function errText(error) {
        if (!error) return 'Lỗi không rõ';
        if (typeof error === 'string') return error;
        return error.message || error.error || error.statusText || String(error);
    }

    function pageGet(key) {
        try { return PAGE.localStorage.getItem(key) || ''; } catch (e) { return ''; }
    }
    function pageSet(key, value) {
        try { PAGE.localStorage.setItem(key, value); return true; } catch (e) { return false; }
    }

    async function gmGet(key, fallback) {
        try {
            if (typeof GM_getValue === 'function') return await GM_getValue(key, fallback);
            if (typeof GM !== 'undefined' && GM && typeof GM.getValue === 'function') return await GM.getValue(key, fallback);
        } catch (e) { failures.push('GM_getValue: ' + errText(e)); }
        return fallback;
    }

    async function gmSet(key, value) {
        try {
            if (typeof GM_setValue === 'function') { await GM_setValue(key, value); return true; }
            if (typeof GM !== 'undefined' && GM && typeof GM.setValue === 'function') { await GM.setValue(key, value); return true; }
        } catch (e) { failures.push('GM_setValue: ' + errText(e)); }
        return false;
    }

    function parseMeta(code) {
        const read = key => {
            const match = String(code).match(new RegExp('^\\s*//\\s*' + key + '\\s+([^\\r\\n]+)', 'm'));
            return match ? match[1].trim() : '';
        };
        return { name: read('@name'), namespace: read('@namespace'), version: read('@version') };
    }

    function compareVersions(a, b) {
        const aa = String(a || '0').split(/[.+-]/).map(x => parseInt(x, 10) || 0);
        const bb = String(b || '0').split(/[.+-]/).map(x => parseInt(x, 10) || 0);
        for (let i = 0; i < Math.max(aa.length, bb.length); i++) {
            const av = aa[i] || 0, bv = bb[i] || 0;
            if (av > bv) return 1;
            if (av < bv) return -1;
        }
        return 0;
    }

    function decodeB64Utf8(encoded) {
        const binary = atob(String(encoded).replace(/\s/g, ''));
        const bytes = Uint8Array.from(binary, ch => ch.charCodeAt(0));
        return new TextDecoder('utf-8').decode(bytes);
    }

    function extractAppSource(fullCode) {
        const match = String(fullCode).match(/const LOCAL_APP_B64 = '([A-Za-z0-9+/=]+)';/);
        if (!match) throw new Error('Không tìm thấy phần Auto tích hợp trong script.user.js.');
        const appSource = decodeB64Utf8(match[1]);
        if (appSource.length < 50000 || !appSource.includes('window.__VLM') || !appSource.includes('window.__vltkOpenPanel')) {
            throw new Error('Phần Auto trong file GitHub không hợp lệ hoặc bị thiếu.');
        }
        return appSource;
    }

    function validateFullScript(code) {
        if (typeof code !== 'string' || code.length < 100000) {
            throw new Error('File GitHub quá ngắn hoặc không phải bản All-in-One đầy đủ.');
        }
        const meta = parseMeta(code);
        if (meta.name !== 'Auto Hoài Niệm + Ns Mod (All-in-One)' || meta.namespace !== 'vlmod' || !meta.version) {
            throw new Error('Sai metadata: cần đúng bản Auto All-in-One.');
        }
        extractAppSource(code);
        return meta;
    }

    function gmRequest(url, apiName) {
        return new Promise((resolve, reject) => {
            let settled = false;
            const finish = (ok, value) => {
                if (settled) return;
                settled = true;
                ok ? resolve(value) : reject(value instanceof Error ? value : new Error(errText(value)));
            };
            const details = {
                method: 'GET', url, timeout: 25000,
                headers: { 'Cache-Control': 'no-cache', 'Accept': 'text/plain, application/vnd.github+json' },
                onload: response => {
                    const status = Number(response && response.status) || 0;
                    if (status < 200 || status >= 300) finish(false, new Error('HTTP ' + status + ' ' + (response && response.statusText || '')));
                    else finish(true, String(response.responseText || ''));
                },
                onerror: e => finish(false, new Error('GM request: ' + errText(e))),
                ontimeout: () => finish(false, new Error('Hết thời gian chờ 25 giây.')),
                onabort: () => finish(false, new Error('Yêu cầu bị hủy.'))
            };
            try {
                let returned;
                if (apiName === 'legacy' && typeof GM_xmlhttpRequest === 'function') returned = GM_xmlhttpRequest(details);
                else if (apiName === 'modern' && typeof GM !== 'undefined' && GM && typeof GM.xmlHttpRequest === 'function') returned = GM.xmlHttpRequest(details);
                else { finish(false, new Error('Không có quyền GM_xmlhttpRequest. Kiểm tra quyền của userscript manager.')); return; }
                if (returned && typeof returned.then === 'function') {
                    returned.then(result => {
                        if (typeof result === 'string') finish(true, result);
                        else if (result && typeof result.responseText === 'string') finish(true, result.responseText);
                    }).catch(e => finish(false, new Error(errText(e))));
                }
            } catch (e) { finish(false, new Error(apiName + ': ' + errText(e))); }
        });
    }

    function decodeGithubApi(text) {
        const json = JSON.parse(text);
        if (!json || !json.content || json.encoding !== 'base64') throw new Error('GitHub API không trả nội dung base64.');
        return decodeB64Utf8(json.content);
    }

    async function requestRemote() {
        failures.length = 0;
        const endpoints = [
            [RAW_URL, 'GitHub Raw', false],
            [JSDELIVR_URL, 'jsDelivr', false],
            [API_URL, 'GitHub API', true]
        ];
        for (const [url, label, isApi] of endpoints) {
            const requestUrl = url + (url.includes('?') ? '&' : '?') + '_=' + Date.now();
            const attempts = [
                async () => {
                    if (typeof PAGE.fetch !== 'function') throw new Error('Không có fetch.');
                    const response = await PAGE.fetch(requestUrl, { method: 'GET', cache: 'no-store', credentials: 'omit', mode: 'cors' });
                    if (!response.ok) throw new Error('HTTP ' + response.status);
                    return await response.text();
                },
                async () => await gmRequest(requestUrl, 'legacy'),
                async () => await gmRequest(requestUrl, 'modern')
            ];
            for (const attempt of attempts) {
                try {
                    let code = await attempt();
                    if (isApi) code = decodeGithubApi(code);
                    const meta = validateFullScript(code);
                    return { code, meta, source: label };
                } catch (e) { failures.push(label + ': ' + errText(e)); }
            }
        }
        throw new Error('Không tải được mã từ GitHub. Chi tiết:\n- ' + failures.join('\n- ') +
            '\n\nKiểm tra mạng và cấp quyền truy cập GitHub cho userscript.');
    }

    async function saveCode(code, version) {
        const localCode = pageSet(CODE_KEY, code);
        const localVersion = pageSet(VERSION_KEY, version);
        const gmCode = await gmSet(CODE_KEY, code);
        const gmVersion = await gmSet(VERSION_KEY, version);
        if (!localCode && !gmCode) throw new Error('Tải được code nhưng không lưu được vào bộ nhớ.');
        if (!localVersion && !gmVersion) throw new Error('Không lưu được số phiên bản.');
    }

    function injectApp(appSource) {
        const doc = PAGE.document;
        if (!doc || !doc.documentElement) throw new Error('Chưa tạo được trang game để nạp Auto.');
        if (PAGE.__VLM && Number(PAGE.__VLM.v) >= 8.41) return;
        const script = doc.createElement('script');
        const nonceElement = doc.querySelector('script[nonce]');
        if (nonceElement) {
            const nonce = nonceElement.nonce || nonceElement.getAttribute('nonce');
            if (nonce) script.setAttribute('nonce', nonce);
        }
        script.textContent = appSource + '\n//# sourceURL=Auto_Hoai_Niem_Ns_Mod_AllInOne.js';
        (doc.head || doc.documentElement).appendChild(script);
        script.remove();
    }

    async function getBootAppSource() {
        const cached = pageGet(CODE_KEY) || await gmGet(CODE_KEY, '');
        if (cached) {
            try {
                const cachedMeta = validateFullScript(cached);
                if (compareVersions(cachedMeta.version, INSTALLED_VERSION) > 0) {
                    console.info('[Auto Updater] Đang dùng cache mới hơn v' + cachedMeta.version);
                    return extractAppSource(cached);
                }
            } catch (e) { console.warn('[Auto Updater] Bỏ qua cache cũ/không hợp lệ:', errText(e)); }
        }
        return decodeB64Utf8(LOCAL_APP_B64);
    }

    async function bridgeCheck(currentVersion) {
        const remote = await requestRemote();
        const current = String(currentVersion || INSTALLED_VERSION);
        return {
            version: remote.meta.version,
            currentVersion: current,
            newer: compareVersions(remote.meta.version, current) > 0,
            source: remote.source
        };
    }

    let updateBusy = false;
    async function bridgeUpdate(currentVersion) {
        if (updateBusy) throw new Error('Đang có yêu cầu cập nhật khác.');
        updateBusy = true;
        try {
            const remote = await requestRemote();
            const current = String(currentVersion || INSTALLED_VERSION);
            if (compareVersions(remote.meta.version, current) <= 0) {
                return { updated: false, version: remote.meta.version, currentVersion: current };
            }
            await saveCode(remote.code, remote.meta.version);
            PAGE.setTimeout(() => PAGE.location.reload(), 700);
            return { updated: true, version: remote.meta.version, source: remote.source };
        } finally { updateBusy = false; }
    }

    function installBridge() {
        const bridge = { version: '1.0.0-all-in-one', check: bridgeCheck, update: bridgeUpdate };
        try {
            Object.defineProperty(PAGE, '__VLMOD_UPDATER_BRIDGE', {
                configurable: true, enumerable: false, writable: true, value: bridge
            });
        } catch (e) {
            try { PAGE.__VLMOD_UPDATER_BRIDGE = bridge; } catch (_e) { }
        }
    }

    function waitForPage(callback) {
        const doc = PAGE.document;
        if (doc && doc.documentElement) { callback(); return; }
        const target = doc || document;
        const observer = new MutationObserver(() => {
            if (target.documentElement) { observer.disconnect(); callback(); }
        });
        observer.observe(target, { childList: true, subtree: true });
    }

    async function boot() {
        try {
            installBridge();
            const appSource = await getBootAppSource();
            waitForPage(() => {
                try {
                    injectApp(appSource);
                    console.info('[Auto All-in-One] Đã nạp Auto Hoài Niệm + Ns Mod v' + INSTALLED_VERSION + '.');
                } catch (e) { console.error('[Auto All-in-One] Không nạp được Auto:', errText(e)); }
            });
        } catch (e) {
            console.error('[Auto All-in-One] Khởi động thất bại:', e);
            try { PAGE.alert('Auto Hoài Niệm không khởi động được:\n' + errText(e)); } catch (_e) { }
        }
    }

    boot();
})();
